static PyObject* sha256_digest(PyObject* self, PyObject* args) {
    Py_buffer view;
    if (!PyArg_ParseTuple(args, "y*", &view)) return NULL;

    const uint8_t* data = (const uint8_t*)view.buf;
    size_t len = view.len;

    uint32_t state[8] = {
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    };

    size_t full = len & ~(size_t)63;
    for (size_t i = 0; i < full; i += 64) {
        sha256_compress(state, data + i);
    }

    // padding
    uint8_t tail[128];
    size_t rem = len - full;
    memcpy(tail, data + full, rem);
    tail[rem] = 0x80;
    size_t padlen;
    if (rem < 56) {
        memset(tail + rem + 1, 0, 56 - rem - 1);
        padlen = 64;
    } else {
        memset(tail + rem + 1, 0, 64 - rem - 1);
        padlen = 128;
    }
    uint64_t bitlen = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) {
        tail[padlen - 1 - i] = (uint8_t)(bitlen >> (8*i));
    }
    for (size_t i = 0; i < padlen; i += 64) {
        sha256_compress(state, tail + i);
    }

    uint8_t out[32];
    for (int i = 0; i < 8; i++) {
        out[4*i]   = (uint8_t)(state[i] >> 24);
        out[4*i+1] = (uint8_t)(state[i] >> 16);
        out[4*i+2] = (uint8_t)(state[i] >> 8);
        out[4*i+3] = (uint8_t)(state[i]);
    }

    PyBuffer_Release(&view);
    return PyBytes_FromStringAndSize((const char*)out, 32);
}

